define('taoDeliveryRdf/controller/Usage/index',['jquery', 'i18n', 'util/url', 'ui/datatable', 'layout/actions/binder'], function ($, __, url) {
  'use strict';

  var lineHeight = 30;
  var searchPagination = 70;
  function getNumRows() {
    var $upperElem = $('.content-container h2');
    var topOffset = $upperElem.length > 0 && $upperElem.offset() ? $upperElem.offset().top : 0;
    var upperHeight = $upperElem.length > 0 ? $upperElem.height() || 0 : 0;
    var marginBottom = $upperElem.length > 0 ? parseInt($upperElem.css('margin-bottom'), 10) || 0 : 0;
    var footerHeight = $('footer.dark-bar').outerHeight() || 0;
    var topSpace = topOffset + upperHeight + marginBottom + lineHeight + searchPagination;
    var availableHeight = $(window).height() - topSpace - footerHeight;
    if (!window.MSInputMethodContext && !document.documentMode && !window.StyleMedia) {
      return 25;
    }
    var computedRows = availableHeight > 0 ? Math.floor(availableHeight / lineHeight) : 1;
    return Math.max(1, Math.min(computedRows, 25));
  }
  function getColumns(mode) {
    if (mode === 'delivery') {
      return [{
        id: 'label',
        label: __('Label'),
        sortable: true
      }, {
        id: 'location',
        label: __('Location'),
        sortable: false
      }];
    }
    return [{
      id: 'label',
      label: __('Label'),
      sortable: true
    }, {
      id: 'location',
      label: __('Location'),
      sortable: true
    }, {
      id: 'publicationTime',
      label: __('Published on'),
      sortable: true
    }];
  }
  function getModeSettings(mode) {
    return {
      filter: mode !== 'delivery',
      paginationStrategyTop: 'none',
      paginationStrategyBottom: mode === 'delivery' ? 'none' : 'simple',
      sortby: mode === 'delivery' ? 'label' : 'publicationTime',
      sortorder: mode === 'delivery' ? 'asc' : 'desc'
    };
  }
  return {
    getModeSettings: getModeSettings,
    getColumns: getColumns,
    start: function start() {
      var urlInfo = url.parse(window.location);
      var $grid = $('.usage-grid');
      var mode = $grid.data('mode');
      var uri = $grid.data('uri');
      if (typeof uri !== 'string' || uri.trim() === '' || mode !== 'delivery' && mode !== 'test') {
        return;
      }
      var dataUrl = mode === 'delivery' ? url.route('getDeliverySourceTestData', 'Usage', 'taoDeliveryRdf', {
        uri: uri
      }) : url.route('getTestDeliveriesUsageData', 'Usage', 'taoDeliveryRdf', {
        uri: uri
      });
      var actions = [{
        id: 'link-action',
        title: __('View'),
        label: __('View'),
        disabled: function disabled() {
          return !this.id;
        },
        action: function action(targetUri) {
          var pathParams = mode === 'delivery' ? {
            ext: 'taoTests',
            section: 'manage_tests',
            structure: 'tests',
            uri: targetUri
          } : {
            ext: 'taoDeliveryRdf',
            section: 'manage_delivery_assembly',
            structure: 'delivery',
            uri: targetUri
          };
          var openedWindow = window.open(url.build(urlInfo.path, pathParams), '_blank', 'noopener,noreferrer');
          if (openedWindow) {
            openedWindow.opener = null;
          }
        }
      }];
      $grid.datatable(Object.assign({
        url: dataUrl,
        labels: {
          filter: mode === 'delivery' ? __('Search Tests') : __('Search Deliveries'),
          title: mode === 'delivery' ? __('Search Tests') : __('Search Deliveries')
        },
        model: getColumns(mode),
        rows: getNumRows(),
        actions: actions
      }, getModeSettings(mode)));
    }
  };
});
