define('taoDeliveryRdf/controller/Publish/index',['jquery', 'i18n', 'util/url', 'layout/actions', 'provider/resources', 'ui/destination/selector', 'ui/feedback', 'ui/taskQueue/taskQueue'], function ($, __, urlHelper, actionManager, resourceProviderFactory, destinationSelectorFactory, feedback, taskQueue) {
  'use strict';
  var refreshTree = function refreshTree(uriResource) {
    actionManager.trigger('refresh', {
      uri: uriResource
    });
  };
  return {
    start: function start() {
      var $container = $('.selector-container');
      var testUri = $container.data('test');
      var testLabel = $container.data('label');
      var resourceProvider = resourceProviderFactory();
      destinationSelectorFactory($container, {
        title: __('Publish "%s" to', testLabel),
        actionName: __('Publish'),
        icon: 'delivery',
        taskQueue: taskQueue,
        taskCreationData: {
          testUri: testUri
        },
        taskCreationUrl: urlHelper.route('publish', 'Publish', 'taoDeliveryRdf'),
        classUri: $container.data('root-class')
      }).on('query', function (params) {
        var self = this;
        params.classOnly = true;
        resourceProvider.getResources(params, true).then(function (resources) {
          self.update(resources, params);
        }).catch(function (err) {
          self.trigger('error', err);
        });
      }).on('finished', function (result, button) {
        if (result.task && result.task.report && Array.isArray(result.task.report.children) && result.task.report.children.length && result.task.report.children[0]) {
          if (result.task.report.children[0].data && result.task.report.children[0].data.uriResource) {
            feedback().info(__('%s completed', result.task.taskLabel), {
              encodeHtml: false
            });
            refreshTree(result.task.report.children[0].data.uriResource);
          } else {
            button.displayReport(result.task.report.children[0], __('Error'));
          }
        }
      }).on('continue', function () {
        refreshTree(testUri);
      }).on('error', function (err) {
        if (err && err.errorMsg) {
          err = err.errorMsg;
        }
        feedback().error(err);
      });
    }
  };
});
